from scipy.optimize import minimize_scalar
def B3(w):
    C=np.cos(w*t);S=np.sin(w*t)
    cols=[np.ones_like(t),x,v,x**2,x**3,v**2,v**3,x*v,x**2*v,x*v**2]
    for g in [C,S]:
        for m in [np.ones_like(t),x,x**2,v,x*v]:
            cols.append(g*m)
    return np.column_stack(cols)
def f3(w):
    X=B3(w); c=np.linalg.lstsq(X,dv_dt,rcond=None)[0]
    return np.mean((X@c-dv_dt)**2)/np.var(dv_dt)
ws=np.linspace(0.05,3,3000); fs=[f3(w) for w in ws]
i=int(np.argmin(fs)); print(ws[i],fs[i])
r=minimize_scalar(f3,bounds=(ws[i]-0.01,ws[i]+0.01),method='bounded',options={'xatol':1e-12})
print(r.x,r.fun)
